  "ui.finalOnboarding.f54f5d4bcd": "您的设置",
  "ui.finalOnboarding.7d2d594053": "您想如何使用 Pixflow？",
  "ui.finalOnboarding.bdf73477f9": "连接 API 服务商",
  "ui.finalOnboarding.28edc3b8f2": "连接您的 AI 订阅",
  "ui.finalOnboarding.f9573d1164": "可以开始创作了",
  "ui.finalOnboarding.45ddd1221b": "WordPress 和 Gutenberg 编辑免费，无需许可证或试用。",
  "ui.finalOnboarding.6072f06060": "激活许可证以开始使用。已经激活？许可证将显示在这里。",
  "ui.finalOnboarding.ae83bc42b4": "选择适合您的方式。随时可在设置中更改。",
  "ui.finalOnboarding.c9e2eb7fcb": "使用服务商提供的 API 密钥。此方式不需要 Bridge。",
  "ui.finalOnboarding.5add76d77c": "Bridge 将此站点连接到电脑上的 AI 智能体。AI 用量由您的服务商账户提供。",
  "ui.finalOnboarding.4813d31d25": "无需连接 AI 即可使用 WordPress 工作区。",
  "ui.finalOnboarding.fbcd710247": "连接已配置完成。请提出问题或描述您想构建的内容。",
  "ui.finalOnboarding.24fba6f166": "连接 AI 订阅",
  "ui.finalOnboarding.82d6b8daef": "通过 Pixflow Design Bridge 使用 Codex、OpenCode 等受支持的智能体。",
  "ui.finalOnboarding.894f66ba11": "使用 API 密钥",
  "ui.finalOnboarding.e76c3bfd0e": "直接连接服务商。API 用量单独计费。",
  "ui.finalOnboarding.1be451ef72": "不使用 AI，继续",
  "ui.finalOnboarding.88e6e83b86": "使用 WordPress 工作区。之后可按需添加 AI。",
  "ui.finalOnboarding.105e56e56f": "为什么选择本地 CLI？",
  "ui.finalOnboarding.5df057fcd7": "API 用量单独计费",
  "ui.finalOnboarding.44e30ed15f": "BYOK 需要 API 密钥。AI 服务商会在 CLI 订阅之外单独收取 API 费用，因此这可能产生额外费用，而不是使用 CLI 账户包含的额度或每周用量限制。",
  "ui.finalOnboarding.5f9b0ae108": "仅限本次会话",
  "ui.finalOnboarding.3c0e1f05da": "仅在此面板会话打开期间保留上下文。重新加载后将重新开始。",
  "ui.finalOnboarding.3efe5537cf": "重新加载后恢复",
  "ui.finalOnboarding.1ccaa4f4ad": "在此浏览器标签页重新加载后恢复限定范围的上下文。",
  "ui.finalOnboarding.a7f9620cca": "此设备上",
  "ui.finalOnboarding.94536fb7d6": "在此设备重启浏览器后，仍保留限定范围的本地上下文。",
  "ui.finalOnboarding.1cd7c231fc": "浮动面板保留设置已更新。",
  "ui.finalOnboarding.d5c52fc3a8": "已请求重置打开的 Bricks 面板的上下文。",
  "ui.finalOnboarding.77d3d7f7d3": "已请求在打开的 Bricks 面板中开始新对话。",
