  "ui.mediaStarter.image1.title": "杂志风格肖像",
  "ui.mediaStarter.image1.tag": "肖像",
  "ui.mediaStarter.image1.prompt": "一位二十多岁后半段的年轻创意总监的杂志风格特写肖像。柔和的自然光透过高大的工作室窗户，使用温暖的中性色调（奶油色、灰褐色、柔黑色），以 85mm f/1.8 浅景深拍摄，锐利目光直视镜头，细微胶片颗粒，素颜感。",
  "ui.mediaStarter.image2.title": "产品主视觉",
  "ui.mediaStarter.image2.tag": "电商",
  "ui.mediaStarter.image2.prompt": "一只哑光陶瓷咖啡杯的高端产品主视觉，放在温暖的奶油色纸质背景上。左上方硬质轮廓光，柔和细长阴影延伸至右下方，杯中升起淡淡蒸汽。正方形裁切，居中构图，上方留出标题空间，画面中无道具或手。",
  "ui.mediaStarter.image3.title": "扁平插画",
  "ui.mediaStarter.image3.tag": "插画",
  "ui.mediaStarter.image3.prompt": "雨天窗边舒适阅读角的扁平矢量插画，使用几何形状和克制的五色调色板（奶油色、陶土色、深青色、焦赭色、柔黑色），以 1.5px 细线点缀，无渐变、无纹理，仅前景扶手椅有柔和投影。",
  "ui.mediaStarter.video1.title": "产品揭幕",
  "ui.mediaStarter.video1.tag": "电影感",
  "ui.mediaStarter.video1.prompt": "5 秒产品揭幕镜头：简约高端护肤瓶放在干净的奶油色石材表面上，镜头左侧柔和侧光，镜头缓慢推进，浅景深焦点从瓶盖轻微转移到标签，动作克制，无文字叠加，画面中无人。",
  "ui.mediaStarter.video2.title": "灯笼特写",
  "ui.mediaStarter.video2.tag": "氛围",
  "ui.mediaStarter.video2.prompt": "6 秒电影感特写：年轻女子在黄金时刻的薄雾松林中捧着发光纸灯笼。浅景深聚焦双眼，镜头轻柔推进，空气中的微粒漂浮在温暖光束中，无对白，仅有森林环境声。",
  "ui.mediaStarter.video3.title": "霓虹街头漂移",
  "ui.mediaStarter.video3.tag": "动作",
  "ui.mediaStarter.video3.prompt": "5 秒夜间街头赛车跟拍，场景是霓虹灯照亮的赛博朋克香港小巷。低角度镜头跟随哑光黑色跑车漂移过急弯，车轮有运动模糊，前方霓虹招牌产生镜头光晕，雨水湿润的柏油路反射灯光，无屏幕文字。",
  "ui.mediaStarter.hyperframes1.title": "放大镜揭示",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "制作一个 5 秒作品：干净画布上只有一行粗体展示文字。让圆形放大镜从左到右移动，经过时通过轻微的玻璃折射扭曲下方字母。使用 HyperFrames html-in-canvas 捕获文本 DOM，并通过类似 vfx-liquid-glass 的处理层叠加镜头着色器。文字使用纯 CSS，玻璃效果为 WebGL 层。",
  "ui.mediaStarter.hyperframes2.title": "CRT 终端场景",
  "ui.mediaStarter.hyperframes2.tag": "复古特效",
  "ui.mediaStarter.hyperframes2.prompt": "制作 CRT 屏幕作品：深色画布，等宽终端文字输入 `npx hyperframes init my-video`，然后调用 `claude` 并使用提示词 'Add a CRT effect using HTML-in-canvas'。通过 html-in-canvas 在实时 DOM 上叠加轻微凸面曲率着色器、扫描线、少量色差和柔和荧光辉光。终端文字保持真实 CSS，使其在着色器处理前像素清晰。",
  "ui.mediaStarter.hyperframes3.title": "数字故障崩解",
  "ui.mediaStarter.hyperframes3.tag": "故障效果",
  "ui.mediaStarter.hyperframes3.prompt": "构建 6 秒作品：深色画布上显示主标题和一行副标题，然后发生强烈数字故障——RGB 通道分离、水平位移条带、短暂帧卡顿，最后恢复干净画面。通过 html-in-canvas 捕获实时 DOM 并叠加故障处理层，使着色器下方的文字保持真实 CSS。",
  "ui.mediaStarter.audio1.title": "品牌旁白",
  "ui.mediaStarter.audio1.tag": "语音",
  "ui.mediaStarter.audio1.prompt": "为产品发布视频制作 30 秒温暖叙事旁白，自信但像交谈，语速适中，品牌名称后短暂停顿。台词：'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' 使用英语、中性北美口音。",
  "ui.mediaStarter.audio2.title": "入门引导旁白",
  "ui.mediaStarter.audio2.tag": "语音",
  "ui.mediaStarter.audio2.prompt": "为移动应用首次启动画面制作 20 秒友好引导旁白。语气安心、带微笑，语速从容而贴心，不像照本宣科。台词：“欢迎来到 Loop。让我们设置您的空间，只需三个简单问题即可开始。之后您可以随时更改这些设置。”",
  "ui.mediaStarter.audio3.title": "故事片段朗读",
  "ui.mediaStarter.audio3.tag": "语音",
  "ui.mediaStarter.audio3.prompt": "用 45 秒以电影感朗读开篇片段。声音低沉、节奏从容，句间留有呼吸，带一点贴近麦克风的亲密感。台词：“这座城市在片刻间沉睡。拉面柜台上方的霓虹招牌闪烁着。街道对面，一扇窗亮着光——午夜这一侧唯一还亮着的窗。”",
